class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        INF = 10**9
        # Map chars to indices 0..25
        w = [ord(c) - ord('a') for c in word]

        # dp[i][c]: min ops to process up to i with s[i]=c
        dp = [[INF]*26 for _ in range(n)]

        for c in range(26):
            dp[0][c] = 0 if c == w[0] else 1

        # Precompute which pairs are allowed (not almost-equal)
        allowed = [[True]*26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                if abs(a - b) <= 1:
                    allowed[a][b] = False

        for i in range(1, n):
            for c in range(26):
                cost = 0 if c == w[i] else 1
                best = INF
                # choose previous letter p such that not almost-equal with c
                for p in range(26):
                    if allowed[c][p]:
                        if dp[i-1][p] < best:
                            best = dp[i-1][p]
                dp[i][c] = best + cost

        return min(dp[n-1])
